const payload = $input.first().json;
const transaction = payload.transaction || {};
const fulfillment_config = payload.configuration?.fulfillment || {};
const mode = fulfillment_config.mode || 'not_applicable';
const customer = payload.customer || {};
const idempotency_key = `shipment_${transaction.id}_${transaction.created_at}`;

let result_success = true;
let result_outcome = 'action_completed';
let new_status = 'fulfillment_pending';
let new_sub_status = null;
let next_action = null;
let fulfillment_data = null;
let error = null;

function validateFulfillmentConfiguration(mode) {
  const missingFields = [];

  if (mode === 'store_pickup') {
    if (!fulfillment_config.store_id) missingFields.push('store_id');
  } else if (mode === 'home_delivery') {
    if (!customer.address) missingFields.push('customer.address');
    if (!customer.city) missingFields.push('customer.city');
    if (!customer.phone) missingFields.push('customer.phone');
  } else if (mode === 'digital_delivery') {
    if (!customer.email) missingFields.push('customer.email');
  }

  return {
    valid: missingFields.length === 0,
    missing: missingFields
  };
}

function buildFulfillmentPayload(mode) {
  const base = {
    fulfillment_id: null,
    idempotency_key: idempotency_key,
    mode: mode,
    status: 'pending',
    created_at: new Date().toISOString(),
    reference_transaction_id: transaction.id
  };

  if (mode === 'store_pickup') {
    return {
      ...base,
      store: {
        store_id: fulfillment_config.store_id,
        store_name: fulfillment_config.store_name || null,
        location: fulfillment_config.store_location || null,
        hours: fulfillment_config.store_hours || null
      },
      customer: {
        name: customer.name,
        phone: customer.phone,
        email: customer.email
      },
      ready_for_pickup_at: null,
      picked_up_at: null,
      pickup_confirmation_code: null
    };
  } else if (mode === 'home_delivery') {
    return {
      ...base,
      shipping_address: {
        street: customer.address,
        city: customer.city,
        postal_code: customer.postal_code || null,
        phone: customer.phone,
        instructions: fulfillment_config.delivery_instructions || null
      },
      carrier: fulfillment_config.carrier || null,
      tracking_number: null,
      estimated_delivery_date: null,
      delivered_at: null,
      delivery_signature_required: fulfillment_config.requires_signature || false
    };
  } else if (mode === 'digital_delivery') {
    return {
      ...base,
      delivery_channel: fulfillment_config.channel || 'email',
      recipient_email: customer.email,
      download_link: null,
      accessed_at: null,
      access_count: 0
    };
  }

  return base;
}

if (mode === 'not_applicable') {
  fulfillment_data = {
    mode: 'not_applicable',
    status: 'skipped',
    note: 'No fulfillment required for this transaction'
  };
  new_status = transaction.status || 'payment_confirmed';
  next_action = 'complete_transaction';
} else {
  const validation = validateFulfillmentConfiguration(mode);

  if (!validation.valid) {
    result_success = false;
    result_outcome = 'missing_data';
    new_status = 'fulfillment_failed';
    new_sub_status = 'missing_fulfillment_data';
    next_action = 'handle_error';
    error = {
      code: 'FULFILLMENT_CONFIGURATION_INCOMPLETE',
      category: 'configuration',
      message: `Required fulfillment data missing for mode: ${mode}`,
      retryable: false,
      details: { missing_fields: validation.missing }
    };
  } else {
    fulfillment_data = buildFulfillmentPayload(mode);

    if (mode === 'store_pickup') {
      new_status = 'ready_for_pickup';
      new_sub_status = 'awaiting_store_confirmation';
      next_action = 'wait_pickup_confirmation';
      result_outcome = 'action_pending';
    } else if (mode === 'home_delivery') {
      new_status = 'awaiting_shipment';
      new_sub_status = 'shipment_scheduled';
      next_action = 'wait_shipment_update';
      result_outcome = 'action_pending';
    } else if (mode === 'digital_delivery') {
      new_status = 'digital_delivery_ready';
      new_sub_status = null;
      next_action = 'complete_transaction';
      result_outcome = 'action_completed';
    }
  }
}

return [{
  json: {
    result: {
      success: result_success,
      outcome: result_outcome
    },
    transaction: {
      transaction_id: transaction.id,
      previous_status: transaction.status,
      current_status: new_status,
      sub_status: new_sub_status,
      next_action: next_action
    },
    route: {
      selected_flow: 'DALIA_M5_Commerce_Orchestrator',
      effective_action: 'resolve_fulfillment_route',
      reason: mode === 'not_applicable' ? 'no_fulfillment_required' : `fulfillment_mode_${mode}`
    },
    response: {
      message_required: false,
      message_type: null,
      reply_text: null,
      requested_fields: []
    },
    data: {
      fulfillment: fulfillment_data || {}
    },
    error: error,
    trace: {
      trace_id: payload.trace?.trace_id || null,
      request_id: payload.trace?.request_id || null,
      workflow: 'DALIA_M5_05_Fulfillment',
      stage: 'fulfillment_processed',
      processed_at: new Date().toISOString()
    }
  }
}];
